class Solution {
    public int minOperations(String s) {
        int n = s.length();
        int cost0 = 0; // cost to make pattern "0101..."
        int cost1 = 0; // cost to make pattern "1010..."
        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            char exp0 = (i % 2 == 0) ? '0' : '1';
            char exp1 = (i % 2 == 0) ? '1' : '0';
            if (c != exp0) cost0++;
            if (c != exp1) cost1++;
        }
        return Math.min(cost0, cost1);
    }
}
